ee:variables.ee:set-variable:
%dw 2.0
output application/json


var keys = vars.input1[1 to -1] map $[0]
var values = vars.input2[1 to -1] map $[0]

var data=(keys zip values) reduce ((item, acc = {}) -> acc ++ { (item[0]): item[1] })

var lessRVO = vars.unitPrices."Less RVO"[0]

---
data mapObject ((value, key) ->
    if (key contains "Export")
        { (key): value - (lessRVO) }
    else
        { (key): value }
)

%dw 2.0
output application/json

var sample = vars.sampleProducts[1 to -4]
var input2 = vars.diffValueSet

---
sample map ((item) -> do {
    var name = item[0]
    ---
    if (input2[name]? )
        { (name): input2[name] }
    else
        { (name): null }
})
